-- Controlled database test. Everything, including generated production/notifications,
-- is rolled back. Never remove the transaction wrapper.
begin;
do $$
declare a uuid; other_agent uuid; owner uuid; cid uuid:=gen_random_uuid(); tid uuid:=gen_random_uuid(); nid uuid:=gen_random_uuid(); sid uuid:=gen_random_uuid(); fields jsonb; r jsonb; d jsonb; v timestamptz; dv jsonb; old_count bigint; denied boolean; row_count int;
begin
 select p.id into a from public.profiles p join public.divisions d on d.id=p.division where p.role='agent' and p.active and not coalesce(p.archived,false) and not d.archived and p.division='vivid_life' limit 1;
 select p.id into other_agent from public.profiles p join public.divisions d on d.id=p.division where p.role='agent' and p.active and not coalesce(p.archived,false) and not d.archived and p.id<>a limit 1;
 select id into owner from public.profiles where is_super_admin and active limit 1;
 if a is null or other_agent is null or owner is null then raise exception 'Need active test roles';end if;
 insert into private.book_unlocks values(a,sid::text,now()+interval '15 minutes'),(other_agent,sid::text,now()+interval '15 minutes'),(owner,sid::text,now()+interval '15 minutes');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'aal','aal2','session_id',sid)::text,true);
 select count(*) into old_count from public.closed_business where agent_id=a;
 fields:=jsonb_build_object('agent_id',a,'client_name','__CRM_WORKSPACE_TEST__','phone','2025550100','carrier','Americo','policy_type','Final Expense','monthly_payment',125,'application_date',current_date-10,'effective_date',current_date-2,'pipeline_stage','submitted','alternate_phone','2025550101','date_of_birth','1980-04-15','mortgage_balance',100000,'email','crm-test@example.invalid','address_line1','Test only','city','Detroit','state','MI','zip','48201','notes','Test record');
 perform public.book_crm_save_v2(cid,fields);
 d:=public.book_crm_detail(cid);r:=d->'client';v:=(r->>'updated_at')::timestamptz;
 if r->>'pipeline_stage'<>'submitted' or r->>'effective_date'<>(current_date-2)::text or r->>'application_date'<>(current_date-10)::text or r->>'alternate_phone'<>'2025550101' or (r->>'mortgage_balance')::numeric<>100000 then raise exception 'New client fields lost: %',r;end if;
 if (select count(*) from public.closed_business where agent_id=a)<>old_count then raise exception 'Submitted policy recorded production';end if;
 perform public.book_crm_save_v2(cid,'{"pipeline_stage":"approved"}',v,null);
 d:=public.book_crm_detail(cid);r:=d->'client';v:=(r->>'updated_at')::timestamptz;
 if (select count(*) from public.closed_business where agent_id=a)<>old_count then raise exception 'Approved policy recorded production';end if;
 perform public.book_crm_save_v2(cid,'{"pipeline_stage":"in_force"}',v,null);
 d:=public.book_crm_detail(cid);r:=d->'client';v:=(r->>'updated_at')::timestamptz;dv:=r->'deal_version';
 if (select count(*) from public.closed_business where agent_id=a)<>old_count+1 or r->>'status'<>'active' then raise exception 'In force failed to record production';end if;
 perform public.book_crm_save_v2(cid,'{"monthly_payment":150}',v,dv);
 d:=public.book_crm_detail(cid);r:=d->'client';
 if (select count(*) from public.closed_business where agent_id=a)<>old_count+1 or (r->>'monthly_payment')::numeric<>150 then raise exception 'Policy edit duplicated production or lost linked update';end if;
 denied:=false;begin perform public.book_crm_save_v2(cid,'{"pipeline_stage":"contacted"}',v,dv);exception when sqlstate 'PT409' then denied:=true;end;if not denied then raise exception 'Stale edit accepted';end if;
 v:=(r->>'updated_at')::timestamptz;dv:=r->'deal_version';
 denied:=false;begin perform public.book_crm_save_v2(cid,jsonb_build_object('effective_date',current_date+2),v,dv);exception when others then denied:=true;end;if not denied then raise exception 'Future coverage marked in force';end if;
 perform public.book_crm_action(cid,'note',nid,'',null,'Follow-up note');perform public.book_crm_action(cid,'note',nid,'',null,'Follow-up note');
 perform public.book_crm_action(cid,'task',tid,'Welcome call',now()-interval '1 hour');perform public.book_crm_action(cid,'task',tid,'Welcome call',now()-interval '1 hour');
 d:=public.book_crm_detail(cid);
 if jsonb_array_length(d->'tasks')<>1 or (select count(*) from private.book_crm_activity where id=nid)<>1 then raise exception 'Action retry duplicated note/task';end if;
 if not exists(select 1 from jsonb_array_elements(d->'activity')j where j->>'body'='Approved → In force') then raise exception 'Stage history missing';end if;
 r:=public.book_crm_workspace(1,'__CRM_WORKSPACE_TEST__',null,'',50,'pipeline');if jsonb_array_length(r->'pipeline')<>1 or (r->'stage_counts'->>'in_force')::int<>1 then raise exception 'Pipeline/search missing record';end if;
 r:=public.book_crm_workspace(1,'__CRM_WORKSPACE_TEST__',null,'',50,'tasks');if (r->>'task_count')::int<>1 or (r->>'followups_due')::int<>1 then raise exception 'Task count/due incorrect';end if;
 perform public.book_crm_action(cid,'complete',tid,'',null,'',(d->'tasks'->0->>'updated_at')::timestamptz);
 d:=public.book_crm_detail(cid);if d->'tasks'->0->>'completed_at' is null then raise exception 'Task not completed';end if;
 r:=public.book_crm_workspace(1,'__CRM_WORKSPACE_TEST__',null,'',50,'tasks','completed');if (r->>'task_count')::int<>1 then raise exception 'Completed task missing';end if;
 perform public.book_crm_action(cid,'reopen',tid,'',null,'',(d->'tasks'->0->>'updated_at')::timestamptz);
 d:=public.book_crm_detail(cid);if d->'tasks'->0->>'completed_at' is not null then raise exception 'Task not reopened';end if;
 perform public.book_crm_save_v2(cid,'{"pipeline_stage":"cancelled"}',v,dv);
 r:=public.book_crm_workspace(1,'__CRM_WORKSPACE_TEST__',null,'cancelled',50,'clients');if (r->>'count')::int<>1 or (r->>'monthly_payment')::numeric<>0 then raise exception 'Cancelled visibility/totals wrong';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other_agent,'aal','aal2','session_id',sid)::text,true);
 r:=public.book_crm_workspace(1,'__CRM_WORKSPACE_TEST__');if (r->>'count')::int<>0 then raise exception 'Foreign record visible';end if;
 denied:=false;begin perform public.book_crm_detail(cid);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Foreign detail visible';end if;
 denied:=false;begin perform public.book_crm_action(cid,'note',gen_random_uuid(),' ',null,'Unauthorized');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Foreign note permitted';end if;
 denied:=false;begin perform public.book_crm_save_v2(cid,'{"pipeline_stage":"contacted"}',v,dv);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Foreign mutation permitted';end if;
 denied:=false;begin perform public.book_crm_save_v2(gen_random_uuid(),fields);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Unauthorized agent assignment permitted';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner,'aal','aal2','session_id',sid)::text,true);
 r:=public.book_crm_workspace(1,'__CRM_WORKSPACE_TEST__');if (r->>'count')::int<>1 then raise exception 'Owner cannot view client';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'aal','aal1','session_id',sid)::text,true);
 denied:=false;begin perform public.book_crm_detail(cid);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Unverified access accepted';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'aal','aal2','session_id',gen_random_uuid())::text,true);
 denied:=false;begin perform public.book_crm_workspace();exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'PIN bypass accepted';end if;
 if has_table_privilege('authenticated','private.book_crm_tasks','select') or has_table_privilege('authenticated','private.book_crm_activity','insert') or has_table_privilege('authenticated','private.book_crm_records','select') or has_function_privilege('anon','public.book_crm_detail(uuid)','execute') then raise exception 'Unsafe grants';end if;
end $$;
select 'PASS: create/edit/reload, independent dates, pipeline, production exactly once, notes, tasks, retries, stale edits, due/completed views, cancelled visibility, ownership, MFA, PIN and grants. All test changes rolled back.' as result;
rollback;
